mapper.select:
SELECT DISTINCT w.name AS name FROM aop_asset a INNER JOIN aop_session s ON s.id = a.session_id INNER JOIN aop_workflow_version wv ON wv.id = s.workflow_version_id INNER JOIN aop_workflow w ON w.id = wv.workflow_id WHERE a.status = 'synced' AND a.asset_type IN ('image', 'video') AND s.session_kind = 'workflow' AND w.name IS NOT NULL AND w.name <> '' AND NOT EXISTS ( SELECT 1 FROM aop_execution r WHERE r.`status` = 'failed' AND a.execution_id IS NOT NULL AND a.execution_id > 0 AND r.id = a.execution_id )
AND a.user_id = #{userId}
ORDER BY name ASC

mapper.update:
UPDATE aop_asset SET updated_at = NOW(), asset_url = CASE id
WHEN #{id} THEN #{url}
END WHERE id IN
#{id}
